 '<path d="M45 77h94v52q-3 30-46 30t-48-30Z" fill="#eae9d4" stroke="#486d59" stroke-width="3"/><path d="M139 85q49-1 22 40l-21 3" fill="none" stroke="#486d59" stroke-width="9"/><ellipse cx="92" cy="77" rx="47" ry="12" fill="#755139"/><path d="M79 56q-18-15 0-28m26 28q-18-15 0-28" fill="none" stroke="#486d59" stroke-width="2"/><path d="M32 167h136" stroke="#486d59" stroke-width="3"/>',
